fn digest_from_yaml(yaml: &str) -> Result<WorkflowDigest, String> {
    let source = crate::parse_workflow_source(yaml).map_err(|e| format!("parse error: {e:?}"))?;
    let compiled = compile_source(&source).map_err(|e| format!("compile error: {e:?}"))?;
    Ok(compiled.digest())
}

